import 'react';

/**
    * Расширение стандартного интерфейса CSSProperties для поддержки кастомных CSS-переменных.
    * Это позволяет использовать типизированные переменные в атрибуте style без приведения типов.
*/
declare module 'react' {
    interface CSSProperties {
        /** переменные для компонента Mascot */

        /** Максимальная ширина текстового облачка (бабла) */
        '--speech-bubble-max-width'?: string;

        /** Вертикальное смещение иконки совы относительно базовой линии */
        '--owl-offset-y'?: string;

        /** Горизонтальное смещение иконки совы (используется для точной подгонки к хвостику) */
        '--owl-offset-x'?: string;

        /** Масштабирование совы (используется для зеркального отображения через scaleX: -1) */
        '--owl-scale'?: string | number;
    }
}